-- =====================================================================
-- BASE DE DONNEES : MAILLE SANITAIRE DE THIES (PostgreSQL + PostGIS)
-- Genere a partir de : Postes_sante_population_offre, Ratios_medecin_infirmier,
--   Superficies_concordance_discordance, Enquete_maille_thies_ville,
--   Maille_sanitaire_Thies_complet_v5, popvillethies.zip (shapefile quartiers)
-- A executer dans pgAdmin (Query Tool) sur la base cible, ex. monsite_db.
-- ATTENTION : le script SUPPRIME puis recree les tables listees ci-dessous.
-- =====================================================================
SET client_encoding = 'UTF8';
CREATE EXTENSION IF NOT EXISTS postgis;
BEGIN;

DROP VIEW IF EXISTS v_quartier_aires CASCADE;
DROP VIEW IF EXISTS v_ratio_commune CASCADE;
DROP VIEW IF EXISTS v_ecart_effectifs CASCADE;
DROP VIEW IF EXISTS v_ratio_poste CASCADE;
DROP TABLE IF EXISTS ratio_poste CASCADE;
DROP TABLE IF EXISTS superficie_poste CASCADE;
DROP TABLE IF EXISTS superficie_synthese CASCADE;
DROP TABLE IF EXISTS grille_distance CASCADE;
DROP TABLE IF EXISTS qualite_gps CASCADE;
DROP TABLE IF EXISTS ratio_population_poste CASCADE;
DROP TABLE IF EXISTS jointure_qgis CASCADE;
DROP TABLE IF EXISTS comparaison_aires CASCADE;
DROP TABLE IF EXISTS aire_theorique CASCADE;
DROP TABLE IF EXISTS qualite_appariement CASCADE;
DROP TABLE IF EXISTS patient_non_rattache CASCADE;
DROP TABLE IF EXISTS sensibilite_seuil CASCADE;
DROP TABLE IF EXISTS aire_reelle CASCADE;
DROP TABLE IF EXISTS aire_administrative CASCADE;
DROP TABLE IF EXISTS modification_enquete CASCADE;
DROP TABLE IF EXISTS enquete_patient CASCADE;
DROP TABLE IF EXISTS population_quartier_2023 CASCADE;
DROP TABLE IF EXISTS quartier CASCADE;
DROP TABLE IF EXISTS norme_oms CASCADE;
DROP TABLE IF EXISTS poste_sante CASCADE;
DROP TABLE IF EXISTS commune CASCADE;

-- ------------------------------------------------------------ referentiels
CREATE TABLE commune (
  id   smallint PRIMARY KEY,
  nom  varchar(30) NOT NULL UNIQUE
);

CREATE TABLE poste_sante (
  id                            smallint PRIMARY KEY,
  nom                           varchar(60) NOT NULL UNIQUE,
  commune_id                    smallint REFERENCES commune(id),
  nb_quartiers_administratifs   smallint,
  quartiers_administratifs      text,
  population_administrative     integer,
  nb_medecins                   smallint,
  nb_infirmiers                 smallint,
  nb_sages_femmes               smallint,
  nb_techniciens_sup            smallint,
  services_essentiels           text,
  svc_consultation              boolean,
  svc_maternite                 boolean,
  svc_pediatrie                 boolean,
  svc_laboratoire               boolean,
  svc_pharmacie                 boolean,
  svc_imagerie                  boolean,
  svc_chirurgie                 boolean,
  svc_radiologie                boolean,
  svc_urgences                  boolean,
  svc_soins_dentaires           boolean,
  svc_consultations_specialisees boolean,
  nb_lits                       smallint,
  nb_radiographie               smallint,
  nb_echographes                smallint,
  nb_scanners                   smallint,
  nb_equip_laboratoire          smallint,
  nb_respirateurs               smallint,
  nb_blocs_operatoires          smallint,
  nb_equip_sterilisation        smallint,
  nb_equip_dentaires            smallint,
  autres_equipements            boolean,
  autres_equipements_precision  text,
  altitude_m                    real,
  precision_gps_m               real,
  geom                          geometry(Point, 4326),
  remarque                      text
);
CREATE INDEX poste_sante_geom_idx ON poste_sante USING gist (geom);

CREATE TABLE norme_oms (
  profession          varchar(40) PRIMARY KEY,
  norme_hab_max       integer NOT NULL,
  equivalent          varchar(60),
  source_remarque     text
);

CREATE TABLE quartier (
  id                 integer PRIMARY KEY,           -- OBJECTID du shapefile
  nom                varchar(80) NOT NULL UNIQUE,   -- QUARTIER (nom officiel)
  nom_ville          varchar(120),                  -- QUARTIER/V
  code_quartier      varchar(13),
  region             varchar(30),
  departement        varchar(30),
  cav                varchar(50),
  type_qvh           varchar(20),
  milieu             varchar(20),
  arrondissement     varchar(30),
  commune_id         smallint REFERENCES commune(id),
  zone_mere          varchar(120),                  -- ZM
  concessions        integer,
  menages            integer,
  hommes             integer,
  femmes             integer,
  population_2023    integer,
  superficie_km2     numeric(8,3),
  densite_hab_km2    numeric(12,1),
  geom               geometry(MultiPolygon, 32628)
);
CREATE INDEX quartier_geom_idx ON quartier USING gist (geom);
CREATE INDEX quartier_commune_idx ON quartier (commune_id);

CREATE TABLE population_quartier_2023 (
  id               smallserial PRIMARY KEY,
  region           varchar(30),
  departement      varchar(30),
  commune_id       smallint REFERENCES commune(id),
  com_arrt_ville   varchar(30),
  quartier_village varchar(120),
  concessions      integer,
  menages          integer,
  hommes           integer,
  femmes           integer,
  population       integer,
  zone_mere        varchar(120)
);

-- ------------------------------------------------------------ enquete patients
CREATE TABLE enquete_patient (
  id                          integer PRIMARY KEY,
  ligne_feuille               integer NOT NULL UNIQUE,   -- n° de ligne Excel d'origine
  enqueteur                   varchar(60),
  poste_id                    smallint NOT NULL REFERENCES poste_sante(id),
  commune_id                  smallint REFERENCES commune(id),
  age                         smallint,
  tranche_age                 varchar(15),
  sexe                        varchar(10),
  niveau_instruction          varchar(20),
  lieu_provenance             varchar(120),
  lieu_provenance_corrige     varchar(120),
  quartier_residence_corrige  varchar(120),
  moyen_transport             varchar(40),
  duree_trajet_min            smallint,
  distance_km                 numeric(6,2),
  distance_brute              varchar(40),   -- valeur saisie d'origine
  raison_proximite            boolean,
  raison_reputation           boolean,
  raison_disponibilite        boolean,
  raison_competence           boolean,
  raison_autres               boolean,
  kobo_id                     bigint,
  kobo_uuid                   uuid,
  date_soumission             timestamp,
  statut                      varchar(30),
  soumis_par                  varchar(60)
);
CREATE INDEX enquete_poste_idx ON enquete_patient (poste_id);

CREATE TABLE modification_enquete (
  id                       smallserial PRIMARY KEY,
  ligne_feuille            integer REFERENCES enquete_patient(ligne_feuille),
  ancien_poste_id          smallint REFERENCES poste_sante(id),
  nouveau_poste_id         smallint REFERENCES poste_sante(id),
  quartier_residence_corrige varchar(120),
  ancienne_commune_id      smallint REFERENCES commune(id),
  nouvelle_commune_id      smallint REFERENCES commune(id),
  motif                    text
);

-- ------------------------------------------------------------ maille sanitaire
CREATE TABLE aire_administrative (
  poste_id          smallint NOT NULL REFERENCES poste_sante(id),
  quartier_id       integer  NOT NULL REFERENCES quartier(id),
  score_correspondance numeric(5,1),
  PRIMARY KEY (poste_id, quartier_id)
);

CREATE TABLE aire_reelle (
  poste_id            smallint NOT NULL REFERENCES poste_sante(id),
  quartier_id         integer  NOT NULL REFERENCES quartier(id),
  nb_patients         smallint,
  pct_flux_poste      numeric(5,1),
  total_patients_poste smallint,
  PRIMARY KEY (poste_id, quartier_id)
);

CREATE TABLE sensibilite_seuil (
  poste_id        smallint NOT NULL REFERENCES poste_sante(id),
  quartier_id     integer  NOT NULL REFERENCES quartier(id),
  retenu_5pct     boolean,
  retenu_10pct    boolean,
  robustesse      varchar(40),
  PRIMARY KEY (poste_id, quartier_id)
);

CREATE TABLE patient_non_rattache (
  id                    smallserial PRIMARY KEY,
  lieu_cite_par_patient varchar(120) NOT NULL,
  nb_patients           smallint
);

CREATE TABLE qualite_appariement (
  poste_id                  smallint PRIMARY KEY REFERENCES poste_sante(id),
  total_patients_reel       smallint,
  pct_patients_non_rattaches numeric(5,1)
);

CREATE TABLE aire_theorique (
  poste_id        smallint NOT NULL REFERENCES poste_sante(id),
  quartier_id     integer  NOT NULL REFERENCES quartier(id),
  commune_id      smallint REFERENCES commune(id),
  population_2023 integer,
  PRIMARY KEY (poste_id, quartier_id)
);

CREATE TABLE comparaison_aires (
  quartier_id            integer PRIMARY KEY REFERENCES quartier(id),
  poste_administratif_id smallint REFERENCES poste_sante(id),
  poste_theorique_id     smallint REFERENCES poste_sante(id),
  postes_reels           text,          -- liste de postes (>= 5 %), separes par des virgules
  critere_geometrique    varchar(20),
  critere_accessibilite  varchar(20)
);

CREATE TABLE jointure_qgis (
  quartier_id            integer PRIMARY KEY REFERENCES quartier(id),
  poste_administratif_id smallint REFERENCES poste_sante(id),
  poste_theorique_id     smallint REFERENCES poste_sante(id),
  poste_reel_dominant_id smallint REFERENCES poste_sante(id),
  pct_reel_dominant      numeric(5,1)
);

CREATE TABLE ratio_population_poste (
  poste_id             smallint PRIMARY KEY REFERENCES poste_sante(id),
  population_desservie integer,
  personnel_total      smallint,
  habitants_par_agent  integer,
  lits                 smallint,
  habitants_par_lit    integer
);

CREATE TABLE grille_distance (
  classe_de_distance varchar(10) PRIMARY KEY,
  nb_points_grille   integer,
  pct_du_territoire  numeric(5,1)
);

CREATE TABLE qualite_gps (
  id          smallserial PRIMARY KEY,
  poste_id    smallint REFERENCES poste_sante(id),
  probleme    varchar(40),
  action_prise text
);

-- ------------------------------------------------------------ ratios OMS (fichier Ratios_medecin_infirmier...)
CREATE TABLE ratio_poste (
  poste_id                   smallint PRIMARY KEY REFERENCES poste_sante(id),
  nb_quartiers_administratifs smallint,
  population_administrative  integer,
  nb_medecins                smallint,
  nb_techniciens_sup         smallint,
  nb_infirmiers              smallint,
  hab_par_technicien_sup     numeric(10,1),   -- NULL = aucun technicien
  hab_par_medecin            numeric(10,1),   -- NULL = aucun medecin
  hab_par_infirmier          numeric(10,1),
  norme_medecin_respectee    boolean,
  norme_technicien_respectee boolean,
  norme_infirmier_respectee  boolean,
  medecins_manquants         smallint,
  techniciens_manquants      smallint,
  infirmiers_manquants       smallint
);

-- ------------------------------------------------------------ superficies
CREATE TABLE superficie_synthese (
  croisement          varchar(40) PRIMARY KEY,
  superficie_ha       numeric(10,2),
  concordance_ha      numeric(10,2),
  discordance_ha      numeric(10,2),
  pct_concordance     numeric(6,4),
  pct_discordance     numeric(6,4)
);

CREATE TABLE superficie_poste (
  croisement          varchar(40) NOT NULL REFERENCES superficie_synthese(croisement),
  poste_id            smallint NOT NULL REFERENCES poste_sante(id),
  superficie_ha       numeric(10,2),
  concordance_ha      numeric(10,2),
  discordance_ha      numeric(10,2),
  pct_concordance     numeric(6,4),
  pct_discordance     numeric(6,4),
  PRIMARY KEY (croisement, poste_id)
);

-- ============================== DONNEES ==============================





















-- ============================== VUES ==============================
-- Synthese par commune (a partir de ratio_poste)
CREATE VIEW v_ratio_commune AS
SELECT c.nom AS commune, count(*) AS nb_postes, sum(r.population_administrative) AS population,
       sum(r.nb_medecins) AS medecins, sum(r.nb_infirmiers) AS infirmiers, sum(r.nb_techniciens_sup) AS techniciens_sup,
       round(sum(r.population_administrative)::numeric / NULLIF(sum(r.nb_medecins), 0), 1)  AS hab_par_medecin,
       round(sum(r.population_administrative)::numeric / NULLIF(sum(r.nb_infirmiers), 0), 1) AS hab_par_infirmier
FROM ratio_poste r JOIN poste_sante p ON p.id = r.poste_id JOIN commune c ON c.id = p.commune_id
GROUP BY c.nom;

-- Ecarts d'effectifs entre le fichier "offre" (poste_sante) et le fichier "ratios" (ratio_poste)
CREATE VIEW v_ecart_effectifs AS
SELECT p.nom AS poste,
       p.nb_medecins AS medecins_offre, r.nb_medecins AS medecins_ratios,
       p.nb_infirmiers AS infirmiers_offre, r.nb_infirmiers AS infirmiers_ratios,
       p.nb_techniciens_sup AS techniciens_offre, r.nb_techniciens_sup AS techniciens_ratios
FROM poste_sante p JOIN ratio_poste r ON r.poste_id = p.id
WHERE p.nb_medecins IS DISTINCT FROM r.nb_medecins
   OR p.nb_infirmiers IS DISTINCT FROM r.nb_infirmiers
   OR p.nb_techniciens_sup IS DISTINCT FROM r.nb_techniciens_sup
   OR p.population_administrative IS DISTINCT FROM r.population_administrative;

-- Les 3 aires par quartier avec noms lisibles + geometrie (pret pour QGIS)
CREATE VIEW v_quartier_aires AS
SELECT q.id, q.nom AS quartier, c.nom AS commune, q.population_2023,
       pa.nom AS poste_administratif, pt.nom AS poste_theorique, pr.nom AS poste_reel_dominant,
       j.pct_reel_dominant, ca.critere_geometrique, ca.critere_accessibilite, q.geom
FROM quartier q
LEFT JOIN commune c ON c.id = q.commune_id
LEFT JOIN jointure_qgis j ON j.quartier_id = q.id
LEFT JOIN comparaison_aires ca ON ca.quartier_id = q.id
LEFT JOIN poste_sante pa ON pa.id = j.poste_administratif_id
LEFT JOIN poste_sante pt ON pt.id = j.poste_theorique_id
LEFT JOIN poste_sante pr ON pr.id = j.poste_reel_dominant_id;

COMMENT ON TABLE quartier IS 'Quartiers de la ville de Thies (RGPH 2023), geometrie en UTM 28N (EPSG:32628)';
COMMENT ON TABLE poste_sante IS 'Postes de sante : personnel, services, equipements, position GPS (EPSG:4326)';
COMMENT ON TABLE enquete_patient IS 'Enquete Kobo aupres des patients : ligne_feuille = n° de ligne du fichier Excel d''origine';

COMMIT;


-- =====================================================================
-- CORRECTIF : alignement de la base sur le memoire (chapitres 3 et 4)
-- A executer APRES base_maille_sanitaire_thies.sql (deja integre a la fin de ce script).
-- Le correctif peut etre rejoue sans risque (il remplace les donnees qu'il gere).
--  * 28 postes publics enquetes (suppression de PS ALAFIA THIES, absent du memoire)
--  * aire administrative : les 68 quartiers rattaches a un poste (28 polygones)
--  * aire reelle : quartiers fournissant plus de 5 % des patients d'un poste, attribues au poste
--    dominant (27 polygones, aucun pour Medina Fall 1) ; flux complets dans flux_patient
--  * aire theorique par quartier : cellule de Thiessen de plus grand recouvrement
--  * indicateurs par poste (tableau 17), classes K-means / CH, type de maille (tableau 15)
--  * grille de distance au poste le plus proche (tableau 8) ; populations RGPH-5 des communes
--  * techniciens superieurs (Darou Salam 8, Silmang 1) repris dans ratio_poste
--  * nettoyage de l'enquete : chaines vides -> NULL, durees negatives -> NULL
-- =====================================================================
BEGIN;

-- ---------------------------------------------------------------- 1. communes : population RGPH-5
ALTER TABLE commune ADD COLUMN IF NOT EXISTS population_2023 integer;
UPDATE commune SET population_2023 = v.p FROM (VALUES (1, 166256), (2, 136138), (3, 88859)) v(id, p) WHERE commune.id = v.id;

-- ---------------------------------------------------------------- 2. postes : numero et nom usuel (memoire)
ALTER TABLE poste_sante ADD COLUMN IF NOT EXISTS numero smallint;
ALTER TABLE poste_sante ADD COLUMN IF NOT EXISTS nom_usuel varchar(60);
UPDATE poste_sante SET numero = v.n, nom_usuel = v.nom FROM (VALUES
  (1, 'Cité Lamy'),
  (2, 'Cité Niakh'),
  (3, 'Darou Salam'),
  (4, 'Diakhao'),
  (5, 'El Hadji Mounirou Ndiéguène'),
  (6, 'Fahu'),
  (7, 'Goutte de Lait'),
  (8, 'Grand Standing'),
  (9, 'Grand Thiès'),
  (10, 'Hersent'),
  (11, 'Kawsara'),
  (12, 'Keur Abdoulaye Yakim'),
  (13, 'Keur Issa'),
  (14, 'Keur Saib Ndoye'),
  (15, 'Mbour 1'),
  (16, 'Mbour 2'),
  (17, 'Mbour 3'),
  (18, 'Médina Fall 1'),
  (19, 'Médina Fall 2'),
  (20, 'Nguinth'),
  (21, 'Parcelles Assainies'),
  (22, 'Petit Thialy'),
  (23, 'Randoulène'),
  (24, 'Sampathe'),
  (25, 'Silmang'),
  (26, 'Takhikao'),
  (27, 'Thiès Nonè'),
  (28, 'ZAC')
) v(n, nom) WHERE poste_sante.id = v.n;

-- ---------------------------------------------------------------- 3. suppression de PS ALAFIA THIES (hors des 28 postes enquetes)
DELETE FROM sensibilite_seuil   WHERE poste_id NOT IN (SELECT id FROM poste_sante WHERE id <= 28);
DELETE FROM qualite_appariement WHERE poste_id NOT IN (SELECT id FROM poste_sante WHERE id <= 28);
DELETE FROM qualite_gps         WHERE poste_id = 29 OR (poste_id = 22 AND probleme = 'MANQUANT');
DELETE FROM superficie_poste    WHERE poste_id = 29;
DELETE FROM ratio_population_poste WHERE poste_id = 29;
DELETE FROM aire_reelle         WHERE poste_id = 29;
DELETE FROM aire_administrative WHERE poste_id = 29;
DELETE FROM aire_theorique      WHERE poste_id = 29;
UPDATE jointure_qgis SET poste_reel_dominant_id = NULL WHERE poste_reel_dominant_id = 29;
UPDATE jointure_qgis SET poste_administratif_id = NULL WHERE poste_administratif_id = 29;
UPDATE jointure_qgis SET poste_theorique_id = NULL WHERE poste_theorique_id = 29;
UPDATE comparaison_aires SET poste_administratif_id = NULL WHERE poste_administratif_id = 29;
UPDATE comparaison_aires SET poste_theorique_id = NULL WHERE poste_theorique_id = 29;
DELETE FROM modification_enquete WHERE ancien_poste_id = 29 OR nouveau_poste_id = 29;
DELETE FROM enquete_patient WHERE poste_id = 29;
DELETE FROM ratio_poste WHERE poste_id = 29;
DELETE FROM poste_sante WHERE id = 29;

-- ---------------------------------------------------------------- 4. aire administrative (68 quartiers -> 28 postes)
DELETE FROM aire_administrative;

-- ---------------------------------------------------------------- 5. flux de patients et aire reelle
DROP TABLE IF EXISTS flux_patient CASCADE;
CREATE TABLE flux_patient (
  poste_id             smallint NOT NULL REFERENCES poste_sante(id),
  quartier_id          integer  NOT NULL REFERENCES quartier(id),
  nb_patients          smallint,
  pct_flux_poste       numeric(5,1),
  total_patients_poste smallint,
  retenu_aire_reelle   boolean,      -- quartier > 5 % des patients du poste ET poste dominant du quartier
  PRIMARY KEY (poste_id, quartier_id)
);
COMMENT ON TABLE flux_patient IS 'Patients enquetes par quartier officiel de residence et par poste (formes tronquees rattachees a tous les quartiers candidats). Ajustements alignes sur le memoire : ESCALE (Goutte de Lait) et DVF (BAYAL) (Randoulene) non retenus.';

DELETE FROM aire_reelle;
SELECT poste_id, quartier_id, nb_patients, pct_flux_poste, total_patients_poste FROM flux_patient WHERE retenu_aire_reelle;

DELETE FROM sensibilite_seuil;
SELECT poste_id, quartier_id, pct_flux_poste > 5, pct_flux_poste > 10,
       CASE WHEN pct_flux_poste > 10 THEN 'STABLE' ELSE 'sensible au seuil' END
FROM flux_patient WHERE pct_flux_poste > 5;

DELETE FROM patient_non_rattache;

DELETE FROM qualite_appariement;

-- ---------------------------------------------------------------- 6. aire theorique par quartier (cellule de Thiessen majoritaire)
DELETE FROM aire_theorique;

-- ---------------------------------------------------------------- 7. jointure et comparaison des aires par quartier
UPDATE jointure_qgis j SET poste_administratif_id = a.poste_id FROM aire_administrative a WHERE a.quartier_id = j.quartier_id;
UPDATE jointure_qgis j SET poste_theorique_id = t.poste_id FROM aire_theorique t WHERE t.quartier_id = j.quartier_id;
UPDATE jointure_qgis j SET poste_reel_dominant_id = r.poste_id, pct_reel_dominant = r.pct_flux_poste FROM aire_reelle r WHERE r.quartier_id = j.quartier_id;
UPDATE jointure_qgis j SET poste_reel_dominant_id = NULL, pct_reel_dominant = NULL WHERE NOT EXISTS (SELECT 1 FROM aire_reelle r WHERE r.quartier_id = j.quartier_id);
UPDATE comparaison_aires c SET
  poste_administratif_id = j.poste_administratif_id,
  poste_theorique_id     = j.poste_theorique_id,
  postes_reels = COALESCE((SELECT string_agg(p.nom, ', ' ORDER BY f.nb_patients DESC) FROM flux_patient f JOIN poste_sante p ON p.id = f.poste_id
                           WHERE f.quartier_id = c.quartier_id AND f.pct_flux_poste > 5), ''),
  critere_geometrique   = CASE WHEN j.poste_administratif_id IS NULL OR j.poste_theorique_id IS NULL THEN 'n.d.'
                               WHEN j.poste_administratif_id = j.poste_theorique_id THEN 'CONCORDANT' ELSE 'DISCORDANT' END,
  critere_accessibilite = CASE WHEN j.poste_administratif_id IS NULL OR j.poste_reel_dominant_id IS NULL THEN 'n.d.'
                               WHEN j.poste_administratif_id = j.poste_reel_dominant_id THEN 'CONCORDANT' ELSE 'DISCORDANT' END
FROM jointure_qgis j WHERE j.quartier_id = c.quartier_id;

-- ---------------------------------------------------------------- 8. indicateurs par poste (tableaux 13, 15 et 17 du memoire)
DROP TABLE IF EXISTS indicateur_poste CASCADE;
CREATE TABLE indicateur_poste (
  poste_id              smallint PRIMARY KEY REFERENCES poste_sante(id),
  numero                smallint,
  superficie_theo_km2   numeric(6,2),   -- polygone de Thiessen decoupe sur la ville
  population_theorique  integer,        -- population communale 2023 repartie au prorata des superficies
  taux_couverture       numeric(5,2),   -- population_theorique / 7 714
  type_maille           varchar(30),    -- tableau 15
  indice_forme          numeric(4,2),   -- IF = S / D2 (cercle = 0,785)
  indice_decentrement   numeric(4,2),   -- ID = d / sqrt(S/pi)
  discordance_ta        numeric(4,2),   -- theorique / administrative
  discordance_ar        numeric(4,2),   -- administrative / reelle (NULL : pas d'aire reelle)
  discordance_tr        numeric(4,2),   -- theorique / reelle
  classe_kmeans         varchar(3),
  classe_ch             varchar(3)
);
COMMENT ON TABLE indicateur_poste IS 'Tableau 17 du memoire (calculs QGIS et R, 2026) ; classes CH : tableau 13 ; type de maille : tableau 15.';

DROP TABLE IF EXISTS classe_offre CASCADE;
CREATE TABLE classe_offre (
  code     varchar(3) PRIMARY KEY,
  methode  varchar(10),
  nb_postes smallint,
  profil   text
);

-- ---------------------------------------------------------------- 9. grille de distance au poste le plus proche (tableau 8)
DELETE FROM grille_distance;
ALTER TABLE grille_distance ALTER COLUMN classe_de_distance TYPE varchar(20);
ALTER TABLE grille_distance ADD COLUMN IF NOT EXISTS ordre smallint;
ALTER TABLE grille_distance ADD COLUMN IF NOT EXISTS distance_max_m integer;
ALTER TABLE grille_distance ADD COLUMN IF NOT EXISTS pct_cumule numeric(5,1);
COMMENT ON TABLE grille_distance IS 'Grille reguliere de 50 m sur les 68 quartiers ; distance a vol d oiseau au poste le plus proche (ponderee par la superficie).';

-- ---------------------------------------------------------------- 10. ratios : techniciens superieurs repris du fichier d'offre
UPDATE ratio_poste r SET
  nb_medecins = p.nb_medecins, nb_infirmiers = p.nb_infirmiers, nb_techniciens_sup = p.nb_techniciens_sup,
  population_administrative = p.population_administrative, nb_quartiers_administratifs = p.nb_quartiers_administratifs
FROM poste_sante p WHERE p.id = r.poste_id;
UPDATE ratio_poste SET
  hab_par_medecin        = round(population_administrative::numeric / NULLIF(nb_medecins, 0), 1),
  hab_par_infirmier      = round(population_administrative::numeric / NULLIF(nb_infirmiers, 0), 1),
  hab_par_technicien_sup = round(population_administrative::numeric / NULLIF(nb_techniciens_sup, 0), 1),
  norme_medecin_respectee    = population_administrative <= 10000 * nb_medecins,
  norme_infirmier_respectee  = population_administrative <= 5000 * nb_infirmiers,
  norme_technicien_respectee = population_administrative <= 5000 * nb_techniciens_sup,
  medecins_manquants    = GREATEST(0, ceil(population_administrative / 10000.0) - nb_medecins),
  infirmiers_manquants  = GREATEST(0, ceil(population_administrative / 5000.0) - nb_infirmiers),
  techniciens_manquants = GREATEST(0, ceil(population_administrative / 5000.0) - nb_techniciens_sup);

-- ---------------------------------------------------------------- 11. nettoyage de l'enquete
UPDATE enquete_patient SET niveau_instruction = NULL WHERE btrim(niveau_instruction) = '';
UPDATE enquete_patient SET moyen_transport = NULL WHERE btrim(moyen_transport) = '';
UPDATE enquete_patient SET quartier_residence_corrige = NULL WHERE btrim(quartier_residence_corrige) = '';
UPDATE enquete_patient SET duree_trajet_min = NULL WHERE duree_trajet_min < 0;

COMMIT;
